107:        &self,
108:        definition: WorkflowDefinition,
109:        inputs: HashMap<String, Value>,
110:    ) -> Result<WorkflowExecutionResult> {
111:        let start = std::time::Instant::now();
112:        let workflow_id = definition.id.clone();
113:
114:        info!(workflow_id = %workflow_id, "Starting workflow execution");
115:
116:        // Create workflow instance
117:        let mut workflow = Workflow::new(definition.clone());
118:        workflow.state = WorkflowState::Running;
119:
120:        // Set initial variables from inputs
121:        for (key, value) in inputs {
122:            workflow.variables.insert(key, value);
123:        }
124:
125:        // Create node instances
126:        let mut nodes: HashMap<String, Box<dyn WorkflowNode>> = HashMap::new();
127:        for node_def in &definition.nodes {
128:            match self
129:                .node_factory
130:                .create_node(&node_def.node_type, &node_def.id, &node_def.config)
131:            {
132:                Ok(node) => {
133:                    nodes.insert(node_def.id.clone(), node);
134:                }
135:                Err(e) => {
136:                    error!(node_id = %node_def.id, error = %e, "Failed to create node");
137:                    return Ok(WorkflowExecutionResult {
138:                        success: false,
139:                        outputs: HashMap::new(),
140:                        error: Some(format!("Failed to create node '{}': {}", node_def.id, e)),
141:                        duration_ms: start.elapsed().as_millis() as u64,
142:                        node_results: HashMap::new(),
143:                    });
144:                }
145:            }
146:        }
147:
148:        let mut node_results: HashMap<String, NodeResult> = HashMap::new();
149:
150:        // Execute nodes in dependency order
151:        loop {
152:            // Check for completion
153:            if workflow.is_complete() {
154:                workflow.state = WorkflowState::Completed;
155:                break;
156:            }
157:
158:            // Check for failure
159:            if workflow.has_failed() {
160:                workflow.state = WorkflowState::Failed;
161:                break;
162:            }
163:
164:            // Get ready nodes
165:            let ready_nodes = workflow.get_ready_nodes();
166:            if ready_nodes.is_empty() {
167:                // No nodes ready but not complete - deadlock or all failed
168:                warn!(workflow_id = %workflow_id, "No nodes ready to execute");
169:                workflow.state = WorkflowState::Failed;
170:                break;
171:            }
172:
173:            // Execute ready nodes (in parallel up to max_parallel)
174:            let batch: Vec<_> = ready_nodes.into_iter().take(self.max_parallel).collect();
175:            if batch.is_empty() {
176:                workflow.state = WorkflowState::Failed;
177:                break;
178:            }
179:
180:            for node_id in batch {
181:                debug!(workflow_id = %workflow_id, node_id = %node_id, "Executing node");
182:
183:                // Get inputs for this node
184:                let node_inputs = workflow.get_node_inputs(&node_id);
185:
186:                // Get node instance
187:                if let Some(node) = nodes.get_mut(&node_id) {
188:                    // Update state
189:                    node.set_state(NodeState::Running);
190:                    workflow
191:                        .node_states
192:                        .insert(node_id.clone(), NodeState::Running);
193:
194:                    // Execute
195:                    match node.execute(node_inputs).await {
196:                        Ok(result) => {
197:                            if result.success {
198:                                workflow.complete_node(&node_id, result.outputs.clone());
199:                                node.set_state(NodeState::Completed);
200:                            } else {
201:                                let error = result.error.clone().unwrap_or_default();
202:                                workflow.fail_node(&node_id, &error);
203:                                node.set_state(NodeState::Failed);
204:                            }
205:                            node_results.insert(node_id.clone(), result);
206:                        }
207:                        Err(e) => {
208:                            error!(node_id = %node_id, error = %e, "Node execution error");
209:                            workflow.fail_node(&node_id, &e.to_string());
210:                            node.set_state(NodeState::Failed);
211:                            node_results
212:                                .insert(node_id.clone(), NodeResult::failure(e.to_string()));
213:                        }
214:                    }
215:                }
216:            }
217:        }
218:
219:        let duration_ms = start.elapsed().as_millis() as u64;
220:        let success = workflow.state == WorkflowState::Completed;
221:
222:        info!(
223:            workflow_id = %workflow_id,
224:            success = success,
225:            duration_ms = duration_ms,
226:            "Workflow execution complete"
227:        );
228:
229:        Ok(WorkflowExecutionResult {
230:            success,
231:            outputs: workflow.get_outputs(),
232:            error: if success {
233:                None
234:            } else {
235:                Some("Workflow execution failed".to_string())
236:            },
237:            duration_ms,
238:            node_results,
239:        })
240:    }
241:}
