91:    pub call_count: u32,
92:    pub total_latency_ms: u64,
93:    pub suggested_name: Option<String>,
94:}
95:
96:impl ExecutionPattern {
97:    pub fn avg_latency_ms(&self) -> u64 {
98:        if self.call_count == 0 {
99:            0
100:        } else {
101:            self.total_latency_ms / self.call_count as u64
102:        }
103:    }
104:}
