106:/// Pattern tracker for optimization suggestions
107:pub struct PatternTracker {
108:    patterns: RwLock<HashMap<String, ExecutionPattern>>,
109:    promotion_threshold: u32,
110:}
111:
112:impl PatternTracker {
113:    pub fn new(promotion_threshold: u32) -> Self {
114:        Self {
115:            patterns: RwLock::new(HashMap::new()),
116:            promotion_threshold,
117:        }
118:    }
119:
120:    /// Record a tool sequence execution
121:    pub async fn record(&self, tools: &[String], latency_ms: u64) -> Option<String> {
122:        let key = tools.join("→");
123:        let mut patterns = self.patterns.write().await;
124:
125:        let pattern = patterns.entry(key.clone()).or_insert(ExecutionPattern {
126:            tool_sequence: tools.to_vec(),
127:            call_count: 0,
128:            total_latency_ms: 0,
129:            suggested_name: None,
130:        });
131:
132:        pattern.call_count += 1;
133:        pattern.total_latency_ms += latency_ms;
134:
135:        if pattern.call_count >= self.promotion_threshold && pattern.suggested_name.is_none() {
136:            let name = format!("combined_{}", &Self::hash_sequence(tools)[..8]);
137:            pattern.suggested_name = Some(name.clone());
138:            Some(name)
139:        } else {
140:            None
141:        }
142:    }
143:
144:    /// Get patterns ready for promotion
145:    pub async fn get_promotion_candidates(&self) -> Vec<ExecutionPattern> {
146:        self.patterns
147:            .read()
148:            .await
149:            .values()
150:            .filter(|p| p.call_count >= self.promotion_threshold)
151:            .cloned()
152:            .collect()
153:    }
154:
155:    fn hash_sequence(tools: &[String]) -> String {
156:        let mut hasher = Sha256::new();
157:        hasher.update(tools.join(":").as_bytes());
158:        hex::encode(hasher.finalize())
159:    }
160:}
