172:#[derive(Clone)]
173:struct CachedResult {
174:    output: simd_json::OwnedValue,
175:    created_at: std::time::Instant,
176:}
177:
178:impl IntermediateCache {
179:    pub fn new(max_entries: usize) -> Self {
180:        Self {
181:            cache: RwLock::new(HashMap::new()),
182:            max_entries,
183:        }
184:    }
185:
186:    pub async fn get(&self, key: &str) -> Option<simd_json::OwnedValue> {
187:        let cache = self.cache.read().await;
188:        cache.get(key).map(|c| c.output.clone())
189:    }
190:
191:    pub async fn put(&self, key: String, output: simd_json::OwnedValue) {
192:        let mut cache = self.cache.write().await;
193:
194:        // Evict oldest if over limit
195:        if cache.len() >= self.max_entries
196:            && let Some(oldest_key) = cache
197:                .iter()
198:                .min_by_key(|(_, v)| v.created_at)
199:                .map(|(k, _)| k.clone())
200:        {
201:            cache.remove(&oldest_key);
202:        }
203:
204:        cache.insert(
205:            key,
206:            CachedResult {
207:                output,
208:                created_at: std::time::Instant::now(),
209:            },
210:        );
211:    }
212:
213:    pub async fn stats(&self) -> CacheStats {
214:        let cache = self.cache.read().await;
215:        CacheStats {
216:            total_entries: cache.len(),
217:            max_entries: self.max_entries,
218:        }
219:    }
220:}
