232:/// Main orchestrator for tool execution
233:pub struct Orchestrator {
234:    config: OrchestratorConfig,
235:    tool_registry: Arc<ToolRegistry>,
236:    /// Shared plugin catalog view used for lookup/routing only.
237:    ///
238:    /// The orchestrator is not allowed to become a second source of truth for
239:    /// plugin schema. It only consumes the already-registered catalog entries.
240:    #[allow(dead_code)]
241:    plugin_catalog: Arc<PluginCatalog>,
242:    execution_tracker: Arc<ExecutionTracker>,
243:    pattern_tracker: Arc<PatternTracker>,
244:    cache: Arc<IntermediateCache>,
245:}
246:
247:impl Orchestrator {
248:    /// Create a new orchestrator
249:    pub fn new(
250:        config: OrchestratorConfig,
251:        tool_registry: Arc<ToolRegistry>,
252:        plugin_catalog: Arc<PluginCatalog>,
253:    ) -> Self {
254:        let pattern_tracker = PatternTracker::new(config.promotion_threshold);
255:        let cache = IntermediateCache::new(1000);
256:        let execution_tracker = ExecutionTracker::new(1000);
257:
258:        Self {
259:            config,
260:            tool_registry,
261:            plugin_catalog,
262:            execution_tracker: Arc::new(execution_tracker),
263:            pattern_tracker: Arc::new(pattern_tracker),
264:            cache: Arc::new(cache),
265:        }
266:    }
267:
268:    /// Execute a single tool
269:    pub async fn execute_tool(
270:        &self,
271:        tool_name: &str,
272:        input: simd_json::OwnedValue,
273:        session_id: Option<String>,
274:    ) -> Result<WorkflowResult> {
275:        require_tool_execution_admission(session_id.as_deref())?;
276:        let request_id = uuid::Uuid::new_v4().to_string();
277:        let start_time = Instant::now();
278:
279:        // Get the tool
280:        let tool = self
281:            .tool_registry
282:            .get(tool_name)
283:            .await
284:            .ok_or_else(|| anyhow::anyhow!("Tool not found: {}", tool_name))?;
285:
286:        // Start tracking
287:        let exec_record = self
288:            .execution_tracker
289:            .start_execution(tool_name, Some(input.clone()), session_id)
290:            .await;
291:
292:        // Execute
293:        let result = tool.execute(input.clone()).await;
294:
295:        // Record result
296:        match &result {
297:            Ok(output) => {
298:                self.execution_tracker
299:                    .complete_execution(
300:                        &exec_record.id,
301:                        Some(simd_json::to_string(output).unwrap_or_default()),
302:                    )
303:                    .await;
304:            }
305:            Err(e) => {
306:                self.execution_tracker
307:                    .fail_execution(&exec_record.id, e.to_string())
308:                    .await;
309:            }
310:        }
311:
312:        let output = result?;
313:        let latency_ms = start_time.elapsed().as_millis() as u64;
314:
315:        Ok(WorkflowResult {
316:            request_id,
317:            success: true,
318:            output,
319:            steps: vec![StepResult {
320:                step_index: 0,
321:                tool_name: tool_name.to_string(),
322:                latency_ms,
323:                cached: false,
324:                success: true,
325:                error: None,
326:            }],
327:            total_latency_ms: latency_ms,
328:            cache_hits: 0,
329:            cache_misses: 1,
330:            used_workstack: false,
331:            resolved_tools: vec![tool_name.to_string()],
332:            error: None,
333:        })
334:    }
335:
336:    /// Execute a sequence of tools (workstack)
337:    pub async fn execute_sequence(
338:        &self,
339:        tool_names: &[&str],
340:        initial_input: simd_json::OwnedValue,
341:        session_id: Option<String>,
342:    ) -> Result<WorkflowResult> {
343:        require_tool_execution_admission(session_id.as_deref())?;
344:        let request_id = uuid::Uuid::new_v4().to_string();
345:        let start_time = Instant::now();
346:
347:        if tool_names.is_empty() {
348:            return Ok(WorkflowResult {
349:                request_id,
350:                success: true,
351:                output: initial_input,
352:                steps: Vec::new(),
353:                total_latency_ms: 0,
354:                cache_hits: 0,
355:                cache_misses: 0,
356:                used_workstack: false,
357:                resolved_tools: Vec::new(),
358:                error: None,
359:            });
360:        }
361:
362:        // Single tool - direct execution
363:        if tool_names.len() < self.config.workstack_threshold {
364:            return self
365:                .execute_tool(tool_names[0], initial_input, session_id)
366:                .await;
367:        }
368:
369:        // Multi-tool workstack execution
370:        let mut steps = Vec::new();
