    fn hash_sequence_with_input(tools: &[&str], input: &simd_json::OwnedValue) -> String {
        let mut hasher = Sha256::new();
        hasher.update(tools.join("→").as_bytes());
        hasher.update(simd_json::to_string(input).unwrap_or_default().as_bytes());
